) N = 10, (x = 1:2, u1 = 3:3, u2 = 4:4, → Δt = 5:5)

 Time Steps Fixed time : All time steps equal (constant Δt) traj_fixed_time = NamedTrajectory(
    (x = randn(2, N), u = randn(1, N), Δt = fill(0.1, N));
    timestep = :Δt,  # symbol pointing to timestep component
    controls = :u,
) N = 10, (x = 1:2, u = 3:3, → Δt = 4:4) Free time : Each time step is a decision variable (with bounds) traj_free_time = NamedTrajectory(
    (x = randn(2, N), u = randn(1, N), Δt = fill(0.1, N));
    timestep = :Δt,
    controls = (:u, :Δt),  # Include Δt in controls for optimization
    bounds = (Δt = (0.01, 0.5),),  # Set bounds on time steps
) N = 10, (x = 1:2, u = 3:3, → Δt = 4:4)

 Initial Conditions Fix the starting state: traj_initial = NamedTrajectory(
    (x = randn(2, N), u = randn(1, N), Δt = fill(0.1, N));
    timestep = :Δt,
    controls = :u,
    initial = (x = [0.0, 0.0],),  # x₁ = [0, 0]
) N = 10, (x = 1:2, u = 3:3, → Δt = 4:4) Can also fix initial controls: traj_initial_u = NamedTrajectory(
    (x = randn(2, N), u = randn(1, N), Δt = fill(0.1, N));
    timestep = :Δt,
    controls = :u,
    initial = (x = [0.0, 0.0], u = [0.0]),  # x₁ = [0, 0], u₁ = 0
) N = 10, (x = 1:2, u = 3:3, → Δt = 4:4)

 Final Conditions Fix the ending state: traj_final = NamedTrajectory(
    (x = randn(2, N), u = randn(1, N), Δt = fill(0.1, N));
    timestep = :Δt,
    controls = :u,
    final = (x = [1.0, 0.0],),  # xₖ = [1, 0]
) N = 10, (x = 1:2, u = 3:3, → Δt = 4:4)

 Goal Conditions Similar to final, but typically used with terminal cost instead of hard constraint: traj_goal = NamedTrajectory(
    (x = randn(2, N), u = randn(1, N), Δt = fill(0.1, N));
    timestep = :Δt,
    controls = :u,
    goal = (x = [1.0, 0.0],),  # target: xₖ → [1, 0]
) N = 10, (x = 1:2, u = 3:3, → Δt = 4:4)

 Scalar Bounds (Symmetric) A single number creates symmetric bounds:  -bound ≤ var ≤ bound traj_scalar_bound = NamedTrajectory(
    (x = randn(2, N), u = randn(1, N), Δt = fill(0.1, N));
